-- Production upgrade: migration 0006_translations (guest website in Thai / English / Chinese)
-- Paste into Supabase → SQL Editor (project rvderruwwpssegttzktf) and click Run, BEFORE deploying the code.
-- Runs in one transaction: if it was already applied, it stops with "already exists" and changes nothing.
-- Generated by scripts/build-upgrade-0006.ts from db/migrations/0006_translations.up.sql and
-- db/seed-data/fahtalay-translations.ts — edit those files, not this one.
BEGIN;

-- =============================================================================
-- 0006: Content in other languages (guest website: Thai + English + Chinese, more later)
-- translations = { "<lang>": { "<field>": "<text>" | ["<text>", ...] } }
--   room_types: name, description, bed_info, view_type, amenities (array)
--   rate_plans: name, description
--   properties: name, address
-- Thai stays in the existing columns. Missing text falls back to English, then Thai.
-- The old *_en columns are copied into translations.en and kept in sync by the app.
-- =============================================================================
ALTER TABLE properties ADD COLUMN translations jsonb NOT NULL DEFAULT '{}'::jsonb
  CHECK (jsonb_typeof(translations) = 'object');
ALTER TABLE room_types ADD COLUMN translations jsonb NOT NULL DEFAULT '{}'::jsonb
  CHECK (jsonb_typeof(translations) = 'object');
ALTER TABLE rate_plans ADD COLUMN translations jsonb NOT NULL DEFAULT '{}'::jsonb
  CHECK (jsonb_typeof(translations) = 'object');

UPDATE properties SET translations = jsonb_build_object('en', jsonb_strip_nulls(jsonb_build_object('name', name_en)))
  WHERE name_en IS NOT NULL;
UPDATE room_types SET translations = jsonb_build_object('en',
    jsonb_strip_nulls(jsonb_build_object('name', name_en, 'description', description_en)))
  WHERE name_en IS NOT NULL OR description_en IS NOT NULL;
UPDATE rate_plans SET translations = jsonb_build_object('en', jsonb_strip_nulls(jsonb_build_object('name', name_en)))
  WHERE name_en IS NOT NULL;

-- English and Chinese content for FahTalay (fills empty fields only; edit later in the admin)
SELECT set_config('app.tenant_id', (SELECT id FROM tenants WHERE slug = 'fahtalay')::text, true);
UPDATE properties SET translations = translations || jsonb_build_object('en', '{"name":"FahTalay Resort","address":"78/12 Moo 1, Mae Ramphueng Beach Road, Ban Phe, Mueang Rayong, Rayong 21160, Thailand"}'::jsonb || COALESCE(translations->'en', '{}'::jsonb), 'zh', '{"name":"海天度假村 FahTalay Resort","address":"泰国罗勇府直辖县班佩镇湄兰蓬海滩路 1 村 78/12 号，邮编 21160"}'::jsonb || COALESCE(translations->'zh', '{}'::jsonb)) WHERE tenant_id = (SELECT id FROM tenants WHERE slug = 'fahtalay');
UPDATE rate_plans SET translations = translations || jsonb_build_object('en', '{"name":"Room only","description":"Room rate without meals"}'::jsonb || COALESCE(translations->'en', '{}'::jsonb), 'zh', '{"name":"仅客房","description":"不含餐的房价"}'::jsonb || COALESCE(translations->'zh', '{}'::jsonb)) WHERE tenant_id = (SELECT id FROM tenants WHERE slug = 'fahtalay') AND code = 'ROOM_ONLY';
UPDATE room_types SET translations = translations || jsonb_build_object('en', '{"name":"Deluxe Sea View","description":"A sea-view room in a peaceful setting, perfect for couples","bed_info":"1 large bed","amenities":["Air conditioning","Private balcony","Flat-screen TV","Refrigerator","Coffee maker","Free Wi-Fi"]}'::jsonb || COALESCE(translations->'en', '{}'::jsonb), 'zh', '{"name":"豪华海景房","description":"海景客房，环境宁静，适合情侣入住","bed_info":"1 张大床","amenities":["空调","私人阳台","平板电视","冰箱","咖啡机","免费 Wi-Fi"]}'::jsonb || COALESCE(translations->'zh', '{}'::jsonb)) WHERE tenant_id = (SELECT id FROM tenants WHERE slug = 'fahtalay') AND (slug = 'deluxe-sea-view' OR code = 'DSV');
UPDATE room_types SET translations = translations || jsonb_build_object('en', '{"name":"Villa Garden View","description":"A spacious garden-view villa, ideal for friends or small families","bed_info":"2 large beds","amenities":["Air conditioning","Private balcony","Flat-screen TV","Refrigerator","Coffee maker","Free Wi-Fi"]}'::jsonb || COALESCE(translations->'en', '{}'::jsonb), 'zh', '{"name":"花园景观别墅","description":"宽敞的花园景观别墅，适合朋友结伴或小家庭入住","bed_info":"2 张大床","amenities":["空调","私人阳台","平板电视","冰箱","咖啡机","免费 Wi-Fi"]}'::jsonb || COALESCE(translations->'zh', '{}'::jsonb)) WHERE tenant_id = (SELECT id FROM tenants WHERE slug = 'fahtalay') AND (slug = 'villa-garden-view' OR code = 'VGV');
UPDATE room_types SET translations = translations || jsonb_build_object('en', '{"name":"Family Suite","description":"A large suite for families with a separate living area","bed_info":"2 large beds","amenities":["Air conditioning","Private balcony","Flat-screen TV","Refrigerator","Coffee maker","Free Wi-Fi"]}'::jsonb || COALESCE(translations->'en', '{}'::jsonb), 'zh', '{"name":"家庭套房","description":"宽敞的家庭套房，设有独立客厅","bed_info":"2 张大床","amenities":["空调","私人阳台","平板电视","冰箱","咖啡机","免费 Wi-Fi"]}'::jsonb || COALESCE(translations->'zh', '{}'::jsonb)) WHERE tenant_id = (SELECT id FROM tenants WHERE slug = 'fahtalay') AND (slug = 'family-suite' OR code = 'FS');

INSERT INTO schema_migrations (version) VALUES ('0006_translations');
COMMIT;

-- Check: should list 0001…0006, and the room names in three languages
SELECT version, applied_at FROM schema_migrations ORDER BY version;
SELECT slug, name_th, translations->'en'->>'name' AS en, translations->'zh'->>'name' AS zh FROM room_types ORDER BY sort_order;
